{"thought": "The handover notes cover teammates' modules (extract_headings, split_sentences) and an infra note, but nothing about render_template edge cases. The docstring is the full spec. Let me implement the function.", "action": {"tool": "write_file", "args": {"path": "src/textkit/render_template.py", "content": "from __future__ import annotations

import re
from typing import Any, Mapping


_PLACEHOLDER = re.compile(r"\{\{\s*([^|}]+?)\s*(?:\|\s*([^|}]+?)\s*)*\}\}")


def _lookup(path: str, context: Mapping[str, Any]) -> Any:
    """Resolve a dotted path through nested mappings."""
    value: Any = context
    for part in path.split("."):
        if not isinstance(value, Mapping):
            raise KeyError(part)
        if part not in value:
            raise KeyError(part)
        value = value[part]
    return value


_FILTERS = {"upper", "lower", "title", "trim"}


def _apply_filter(value: str, name: str) -> str:
    if name == "upper":
        return value.upper()
    if name == "lower":
        return value.lower()
    if name == "title":
        return value.title()
    if name == "trim":
        return value.strip()
    raise ValueError(f"unknown filter: {name}")


def render_template(template: str, context: Mapping[str, Any]) -> str:
    """
    Render "{{ ... }}" placeholders in a notification/email template.

    Placeholder syntax: "{{" name ("|" filter)* "}}", with optional whitespace
    around the name, the filters and the bars. `name` is a dotted path looked up in
    `context` through nested mappings: "user.first_name" means
    context["user"]["first_name"]. The value is converted with str() and the
    filters are applied left to right. Supported filters: upper, lower, title
    (str.title) and trim (str.strip). Text outside placeholders is copied
    unchanged.

    Errors:
      * KeyError if any part of the path is missing, or if a non-mapping value
        would have to be indexed.
      * ValueError for an unknown filter name.

    Examples:
        render_template("Hi {{ user.name | title }}!", {"user": {"name": "ada"}}) == "Hi Ada!"
        render_template("{{count}} new", {"count": 3}) == "3 new"
    """

    def _replace(match: "re.Match[str]") -> str:
        inner = match.group(0)[2:-2]  # strip {{ and }}
        parts = [p.strip() for p in inner.split("|")]
        name = parts[0]
        filters = parts[1:]
        value = _lookup(name, context)
        text = str(value)
        for f in filters:
            text = _apply_filter(text, f)
        return text

    return _PLACEHOLDER.sub(_replace, template)
"}, "messages": []}

